// Gmail and Microsoft Graph disagree on every field name, and SHIPMATE accepts Graph's
// spelling because that is what v2 spoke. Normalising here rather than in SHIPMATE keeps
// the mailbox vendor a detail of this workflow — swapping back to Graph, or adding a
// second mailbox, is then a new workflow rather than a change to the service.
const out = [];

for (const item of $input.all()) {
  const m = item.json;

  // Gmail nests headers; n8n flattens some of them but not reliably across versions.
  const headers = m.headers ?? {};
  const subject = m.subject ?? headers.subject ?? '';
  const from = m.from?.value?.[0]?.address ?? m.From ?? headers.from ?? '';

  // Prefer the HTML part when both exist: it is what the sender actually wrote, and
  // SHIPMATE strips the markup itself.
  const html = m.html ?? m.textHtml ?? '';
  const text = m.text ?? m.textPlain ?? m.snippet ?? '';

  out.push({
    json: {
      messageId: m.id ?? m.messageId ?? m.threadId,
      // Carried through separately from messageId. A partner's reply has its own
      // message id but shares the thread with the request we sent, and the thread is
      // the only thing that links an answer back to the question.
      threadId: m.threadId ?? m.id ?? null,
      subject,
      from,
      body: html || text,
      isHtml: Boolean(html),
      receivedAt: m.date ?? m.internalDate ?? new Date().toISOString(),
    },
  });
}

return out;
